 public static class TransmissionMath {
  static void Need(bool ok,string error){if(!ok)throw new ArgumentException(error);}
  public static double Willis(double sun,double ring,double sunRpm,double ringRpm){Need(sun>0&&ring>0,"Числа зубьев должны быть положительными.");return (sun*sunRpm+ring*ringRpm)/(sun+ring);}
  public static double WormEfficiency(double lead,double mu,double alpha){double rho=Math.Atan(mu/Math.Cos(alpha));return Math.Tan(lead)/Math.Tan(lead+rho);}
  public static Result Calculate(Parameters input){var r=new Result{P=Engine.Clone(input)};var p=r.P;var e=new TransmissionEngineering();r.Engineering=e;try{
   foreach(var prop in typeof(Parameters).GetProperties().Where(x=>x.PropertyType==typeof(double)))Need(!double.IsNaN((double)prop.GetValue(p,null))&&!double.IsInfinity((double)prop.GetValue(p,null)),"Некорректное число: "+prop.Name);
   Need(p.Kind>=5&&p.Kind<=12,"Неизвестная передача.");Need(p.Module>=.15&&p.Module<=10&&p.Teeth>=12&&p.Teeth<=160,"Модуль 0,15–10 мм; ведущие зубья 12–160.");Need(p.Ratio>=1&&p.Ratio<=120&&p.Thickness>=1&&p.Thickness<=100,"Отношение 1–120, ширина 1–100 мм.");Need(p.Clearance>=0&&p.Clearance<=2&&p.Wall>=2&&p.Wall<=30,"Зазор 0–2 мм; стенка 2–30 мм.");Need(p.Shaft>=1&&p.OutputShaft>=1&&p.Shaft<=100&&p.OutputShaft<=100,"Проверьте диаметры валов.");Need(p.Efficiency>0&&p.Efficiency<=1&&p.InputTorque>=0&&p.InputTorque<=10000&&Math.Abs(p.InputRpm)<=100000,"КПД (0;1], момент 0–10000 Н·м, |об/мин| ≤ 100000.");Need(p.PressureAngle>=14.5&&p.PressureAngle<=30,"Угол давления 14,5–30°.");Need(p.MotorPreset>=0&&p.MotorPreset<Engine.PresetNames.Length,"Неизвестный двигатель.");Need(new[]{p.MotorFrame,p.MotorMount,p.MotorPilot,p.MotorHole,p.MotorLength}.All(x=>x>=0)&& (p.MotorFrame==0||p.MotorPilot+2*p.Clearance<p.MotorFrame&&p.MotorMount+p.MotorHole+2*p.Clearance<p.MotorFrame),"Монтажные размеры мотора не помещаются во фланце.");Need(p.ModelInputBearingB>0&&p.BearingWidth>0&&p.ModelGap>=.05&&p.ModelBolt>0,"Проверьте опоры, монтажный зазор и крепёж.");
   r.Z1=p.Teeth;r.Z2=(int)Math.Round(p.Teeth*p.Ratio);Need(r.Z2<=600,"Ведомое колесо: не более 600 зубьев.");double alpha=p.PressureAngle*Math.PI/180;e.Efficiency=p.Efficiency;e.SpeedGain=-1.0*p.Teeth/r.Z2;e.WheelDiameter=p.Module*r.Z2;
   if(p.Kind==5||p.Kind==10){Need(p.WormStarts>=1&&p.WormStarts<=8&&p.WormDiameterFactor>=6&&p.WormDiameterFactor<=30&&p.Friction>=0&&p.Friction<=.5,"Червяк: 1–8 заходов, q 6–30, трение 0–0,5.");r.Z1=p.WormStarts;r.Z2=(int)Math.Round(p.Ratio*p.WormStarts);Need(r.Z2>=12&&r.Z2<=600,"Червячное колесо: 12–600 зубьев.");e.SpeedGain=-1.0*r.Z1/r.Z2;e.WormDiameter=p.Module*p.WormDiameterFactor;e.WheelDiameter=p.Module*r.Z2;e.Centre=(e.WormDiameter+e.WheelDiameter)/2;e.LeadAngle=Math.Atan((double)p.WormStarts/p.WormDiameterFactor);e.Efficiency=WormEfficiency(e.LeadAngle,p.Friction,alpha);Need(e.Efficiency>0&&e.Efficiency<=1,"Недопустимая оценка КПД червяка.");e.SelfLockEstimate=Math.Cos(alpha)*Math.Tan(e.LeadAngle)<=p.Friction;e.Warnings.Add("Самоторможение — оценка трения в контакте; не подтверждает удержание нагрузки. Потери подшипников/смазки не включены.");if(p.Kind==10)Need(p.GloboidDepth>0&&p.GloboidDepth<e.WormDiameter*.2,"Глубина глобоидной огибающей: больше 0 и меньше 0,2d червяка.");}
   if(p.Kind==6||p.Kind==9){Need(p.ShaftAngle>=45&&p.ShaftAngle<=135,"Угол валов 45–135°.");double sigma=p.ShaftAngle*Math.PI/180;e.Cone1=Math.Atan2(Math.Sin(sigma),(double)r.Z2/r.Z1+Math.Cos(sigma));e.Cone2=sigma-e.Cone1;Need(e.Cone1>0&&e.Cone2>0&&e.Cone1<Math.PI/2&&e.Cone2<Math.PI/2,"Поддерживаются два острых делительных конуса.");e.ConeDistance=p.Module*r.Z1/(2*Math.Sin(e.Cone1));Need(p.Thickness<=e.ConeDistance/3,"Ширина конического венца должна быть не больше трети конусного расстояния.");if(p.Kind==9){Need(Math.Abs(p.AxisOffset)>0&&Math.Abs(p.AxisOffset)<p.Module*r.Z2*.3,"Гипоидная компоновка: ненулевое смещение <0,3d колеса.");Need(Math.Abs(p.SpiralAngle)<=45,"Угол спирали от −45 до 45°.");e.Warnings.Add("Конусы и силы рассчитаны для эквивалентной конической пары; при смещении это только оценка, не гипоидное сопряжение.");}}
   if(p.Kind==7){Need(p.RvPins>=8&&p.RvPins<=80&&p.CrankCount>=2&&p.CrankCount<=4&&p.Discs>=1&&p.Discs<=2,"RV: 8–80 пальцев, 2–4 кривошипа, 1–2 диска.");Need((r.Z1+r.Z2)%p.CrankCount==0,"RV: (z1+z2) должно делиться на число кривошипов.");e.SpeedGain=1/(1+(double)r.Z2/r.Z1*p.RvPins);e.Centre=p.Module*(r.Z1+r.Z2)/2;Need(e.Centre+p.Module*(r.Z2+2)/2<p.Radius+p.Roller/2+p.Wall,"Первичная ступень RV не помещается в кольце: увеличьте радиус или уменьшите модуль/отношение.");var cp=CycleParameters(p);var cr=Engine.Calculate(cp);Need(cr.Valid,"Циклоидальная часть RV: "+string.Join("; ",cr.Errors));r.Stages.Add(cr);r.Profile=cr.Profile;r.Pins=p.RvPins;r.Lobes=p.RvPins-1;e.Warnings.Add("RV: i=1+(z2/z1)·N. Кривошипы движутся относительно водила; профиль диска переиспользует циклоидальный расчёт.");}
   if(p.Kind==8){Need(p.PlanetTeeth>=12&&p.PlanetTeeth<=100&&p.SecondPlanetTeeth>=12&&p.SecondPlanetTeeth<=100&&p.Planets>=2&&p.Planets<=6,"Сателлиты: 12–100 зубьев, количество 2–6.");r.Zp=p.PlanetTeeth;r.Z2=r.Z1+p.PlanetTeeth+p.SecondPlanetTeeth;double k=(double)r.Z2*p.PlanetTeeth/(r.Z1*p.SecondPlanetTeeth);Need((r.Z1*p.SecondPlanetTeeth+r.Z2*p.PlanetTeeth)%(Gcd(p.PlanetTeeth,p.SecondPlanetTeeth)*p.Planets)==0,"Несовместимая равномерная фазировка составных сателлитов.");e.Centre=p.Module*(r.Z1+p.PlanetTeeth)/2;Need(p.Module*(Math.Max(p.PlanetTeeth,p.SecondPlanetTeeth)+2)+p.Clearance<2*e.Centre*Math.Sin(Math.PI/p.Planets),"Соседние составные сателлиты пересекаются.");Need(p.FixedMember>=0&&p.FixedMember<=3,"Схема фиксации: 0 — кольцо, 1 — водило, 2 — солнце, 3 — два входа.");e.SpeedGain=p.FixedMember==0?1/(1+k):p.FixedMember==1?-1/k:p.FixedMember==2?k/(1+k):1/(1+k);if(p.FixedMember==3){Need(Math.Abs(p.SecondInputRpm)<=100000,"Недопустимые обороты второго входа.");e.MultiInput=true;e.OutputRpm=Willis(1,k,p.InputRpm,p.SecondInputRpm);e.Warnings.Add("Два входа: скорость водила по Уиллису. Момент выхода не определён одним входным моментом; распределение мощности здесь не решается.");}}
   if(p.Kind==11){Need(p.InnerPolePairs>=1&&p.InnerPolePairs<=30&&p.OuterPolePairs>=2&&p.OuterPolePairs<=100&&p.MagnetThickness>=1&&p.AirGap>=.1&&p.AirGap<=5,"Проверьте полюсные пары, толщину магнитов и воздушный зазор.");r.Z1=p.InnerPolePairs;r.Z2=p.OuterPolePairs;e.SpeedGain=-(double)r.Z1/r.Z2;Need(p.Radius>p.Shaft/2+3*p.MagnetThickness+2*p.AirGap+5,"Магнитные роторы не помещаются в радиусе.");e.Warnings.Add("Модулятор закреплён, число сегментов p1+p2. Номинальный/предельный момент неизвестен без FEA и данных магнитов.");}
   if(p.Kind==12){Need(p.RackLength>=4*Math.PI*p.Module&&p.RackLength<=2000&&p.RackTravel>=0&&p.RackTravel<=p.RackLength-4*Math.PI*p.Module,"Рейка: длина ≥4πm; ход оставляет не менее двух зубьев с каждой стороны.");e.Linear=true;e.SpeedGain=p.Module*p.Teeth/2;Need(p.RackPosition>=-p.RackTravel/2&&p.RackPosition<=p.RackTravel/2,"Положение рейки за пределами хода.");r.Z2=0;}
   Need(p.Shaft<(p.Kind==11?p.Radius/2:p.Kind==5||p.Kind==10?e.WormDiameter-2.5*p.Module:p.Module*(r.Z1-2.5))&&p.OutputShaft<(p.Kind==11?p.Radius:p.Kind==12?p.Module*r.Z1:p.Module*(r.Z2-2.5)),"Вал не помещается в корне зубчатого колеса.");
   r.Actual=e.Linear?1:1/Math.Abs(e.SpeedGain);r.Spacing=e.Centre;e.InputPower=p.InputTorque*Math.Abs(p.InputRpm)*Math.PI/30;if(!e.MultiInput)e.OutputRpm=p.InputRpm*e.SpeedGain;e.OutputPower=e.InputPower*e.Efficiency;e.OutputTorque=e.MultiInput||e.Linear?double.NaN:p.InputTorque*r.Actual*e.Efficiency;
   if(e.Linear){e.LinearSpeed=p.InputRpm*Math.PI*p.Module*p.Teeth/60;e.OutputForce=p.InputTorque*1000/(p.Module*p.Teeth/2)*e.Efficiency;e.Tangential=e.OutputForce;e.Radial=e.Tangential*Math.Tan(alpha);}else if(p.Kind!=11&&!e.MultiInput){double dm=p.Kind==6||p.Kind==9?p.Module*p.Teeth-p.Thickness*Math.Sin(e.Cone1):p.Kind==5||p.Kind==10?e.WormDiameter:p.Module*p.Teeth;e.Tangential=2000*p.InputTorque/dm;e.Radial=e.Tangential*Math.Tan(alpha);if(p.Kind==6||p.Kind==9){e.Axial=e.Radial*Math.Sin(e.Cone1);e.Radial*=Math.Cos(e.Cone1);e.OutputRadial=e.Tangential*Math.Tan(alpha)*Math.Cos(e.Cone2);e.OutputAxial=e.Tangential*Math.Tan(alpha)*Math.Sin(e.Cone2);}else if(p.Kind==5||p.Kind==10){e.OutputRadial=2000*e.OutputTorque/e.WheelDiameter*Math.Tan(alpha)/Math.Cos(e.LeadAngle);e.Axial=2000*e.OutputTorque/e.WheelDiameter;e.OutputAxial=e.Tangential;e.Radial=e.OutputRadial;}}
   r.Gear1=Engine.Involute(p.Teeth,p.Module,false,p.PressureAngle);if(r.Z2>=8&&p.Kind!=11)r.Gear2=Engine.Involute(r.Z2,p.Module,p.Kind==8,p.PressureAngle);r.Metric("Достоверность геометрии","Геометрически рассчитано: размеры и кинематика; профиль — см. ограничения");r.Metric("Подтверждено специализированной проверкой","Нет: контакт, прочность, ресурс и допустимый момент не подтверждены");r.Metric(e.Linear?"Линейная скорость":"Выходная скорость",Engine.F(e.Linear?e.LinearSpeed:e.OutputRpm)+(e.Linear?" мм/с":" об/мин"));r.Metric("КПД (оценка)",Engine.F(e.Efficiency));r.Metric("Входная мощность",Engine.F(e.InputPower)+" Вт");r.Metric(e.Linear?"Выходное усилие при заданном КПД":"Теоретический выходной момент",e.MultiInput?"Не определён для двух входов":Engine.F(e.Linear?e.OutputForce:e.OutputTorque)+(e.Linear?" Н":" Н·м"));r.Metric("Силы входа Ft / Fr / Fa (оценка)",p.Kind==11||e.MultiInput?"Не определены":Engine.F(e.Tangential)+" / "+Engine.F(e.Radial)+" / "+Engine.F(e.Axial)+" Н");if(p.Kind==5||p.Kind==10){r.Metric("d1 / d2 / a",Engine.F(e.WormDiameter)+" / "+Engine.F(e.WheelDiameter)+" / "+Engine.F(e.Centre)+" мм");r.Metric("Угол подъёма",Engine.F(e.LeadAngle*180/Math.PI)+"°");r.Metric("Условие самоторможения (оценка)",e.SelfLockEstimate?"Выполнено в модели трения":"Не выполнено");}if(p.Kind==6||p.Kind==9)r.Metric("Конусы δ1 / δ2 / R",Engine.F(e.Cone1*180/Math.PI)+"° / "+Engine.F(e.Cone2*180/Math.PI)+"° / "+Engine.F(e.ConeDistance)+" мм");
   r.Notes.Add(TransmissionCatalog.All[p.Kind].Limit);r.Notes.AddRange(e.Warnings);r.Notes.Add("Приближённая инженерная оценка: силы рассчитаны без динамики и распределения контакта. Напряжения, запас и ресурс неизвестны без материалов и специального расчёта. Теоретический момент не является допустимым рабочим.");
   var bounds=TransmissionGeometry.Estimate(r);r.Width=bounds[1]-bounds[0];r.Height=bounds[3]-bounds[2];r.Depth=bounds[5]-bounds[4];if(p.Overall>0)Need(Math.Max(r.Width,r.Height)<=p.Overall+.01,"Механизм не помещается в заданный габарит. Измените модуль или снимите ограничение.");
  TransmissionLoads.Append(r);
  }catch(Exception ex){r.Error(ex.Message,"Ratio","Module","Teeth","Thickness");}return r;}
  static int Gcd(int a,int b){while(b!=0){int c=a%b;a=b;b=c;}return a;}
  public static Parameters CycleParameters(Parameters p){return new Parameters{Kind=0,RingOutput=false,Ratio=p.RvPins-1,Radius=p.Radius,Roller=p.Roller,Eccentric=p.Eccentric,Clearance=p.Clearance,OutputRadius=p.Radius*.42,OutputPin=3,OutputPins=Math.Max(3,p.CrankCount),Bore=8,Shaft=3,Web=1,Discs=p.Discs,Thickness=p.Thickness,Wall=p.Wall,Overall=0};}
 }
